<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
import { useRouter } from 'vue-router';
import AppLayout from '@/components/layout/AppLayout.vue';
import { useDebtHoldStore } from '@/stores/debtHold';
import { apiFetch } from '@/lib/api';
import { formatPen } from '@/lib/financeMoney';
import type { ServiceContract } from '@/types/domain';
const store=useDebtHoldStore(),router=useRouter(),tab=ref('pending'),search=ref(''),error=ref('');
const tabs=[['pending','Pendientes de revisión'],['suspended','Servicios suspendidos'],['paid','Por reactivar'],['errors','Errores / sin verificar'],['history','Historial']];
const rows=computed(()=>store.pending.filter(c=>(tab.value==='history'||tab.value==='errors'||(tab.value==='paid'?false:c.debt_hold_status===tab.value))&&`${c.contract_number} ${c.clients?.first_name} ${c.clients?.last_name}`.toLowerCase().includes(search.value.toLowerCase())));
const detail=ref<{contractId:string;ontId:string|null;reasons:string[];technicalState:string;executionEnabled:false}|null>(null),detailContract=ref<ServiceContract|null>(null),checking=ref(false);
async function inspect(c:ServiceContract){detailContract.value=c;detail.value=null;checking.value=true;try{detail.value=await apiFetch(`/api/debt-hold/${c.id}/preview`);}catch(e){error.value=e instanceof Error?e.message:'No se pudo verificar';}finally{checking.value=false;}}
const events=ref<{created_at:string;event_type:string;detail:string;created_by:string|null}[]|null>(null);
async function history(c:ServiceContract){detailContract.value=c;events.value=await store.fetchEvents(c.id) as typeof events.value;}
onMounted(()=>store.fetchPending().catch(e=>error.value=e.message));
</script>
<template>
 <AppLayout><section class="finance-workspace"><header class="finance-header"><div><span class="finance-eyebrow">COMERCIAL · SERVICIOS</span><h1>Cortes por deuda</h1><p>Estado financiero y técnico por contrato. Revisión humana antes de operar.</p></div><button class="btn-secondary" @click="router.push('/facturacion')">Consultar facturación</button></header><div class="finance-warning"><b>Operaciones técnicas bloqueadas</b><span>Los históricos no conciliados no autorizan suspensión ni reactivación. Esta fase solo permite consultar y verificar vínculos.</span></div><nav class="finance-tabs"><button v-for="[key,label] in tabs" :key="key" :class="{active:tab===key}" @click="tab=key">{{ label }}</button></nav><div class="finance-metrics" style="margin-top:20px"><article><span>Marcados pendientes</span><strong>{{ store.pending.filter(c=>c.debt_hold_status==='pending').length }}</strong><small>Marcas históricas, no deuda certificada</small></article><article><span>Suspensión registrada</span><strong>{{ store.pending.filter(c=>c.debt_hold_status==='suspended').length }}</strong><small>No equivale a verificación técnica</small></article><article><span>Estado técnico real</span><strong>Sin verificar</strong><small>Sin consultas a equipos en esta fase</small></article><article><span>Habilitación operativa</span><strong>Pendiente</strong><small>Conciliación y piloto por aprobar</small></article></div><div class="finance-table-tools"><input v-model="search" placeholder="Buscar cliente o contrato" aria-label="Buscar corte"><span class="finance-help">Hasta 200 contratos · historial bajo demanda · sin escaneo periódico</span></div><p v-if="error" class="finance-error" role="alert">{{ error }}</p><div class="finance-table"><table><thead><tr><th>Cliente / contrato</th><th>Servicio</th><th>Factura señalada</th><th>Importe de referencia</th><th>Estado comercial</th><th>Estado técnico</th><th>Conciliación</th><th>Acciones</th></tr></thead><tbody><tr v-for="c in rows" :key="c.id"><td><button class="finance-link" @click="router.push(`/clientes/${c.client_id}/servicios/${c.id}`)">{{ c.clients?.first_name }} {{ c.clients?.last_name }}</button><small>{{ c.contract_number }}</small></td><td>{{ c.plans?.name??c.service_type }}</td><td>{{ c.invoices?.invoice_number??'Sin factura' }}<small>{{ c.invoices?.due_date }}</small></td><td>{{ formatPen(c.invoices?.amount) }}<small>No es deuda total certificada</small></td><td><span class="finance-badge">{{ c.debt_hold_status==='suspended'?'Suspensión registrada':'Revisión pendiente' }}</span><small>Contrato {{ c.status }}</small></td><td>Desconocido<small>Sin verificación en equipos</small></td><td>{{ c.finance_reconciled_at?'Aprobada':'No conciliado' }}</td><td><div class="finance-row-actions"><button class="finance-link" @click="inspect(c)">Verificar servicio</button><button class="finance-link" @click="history(c)">Historial</button><button class="finance-link" @click="router.push('/facturacion')">Pago / deuda</button><button disabled title="Requiere conciliación y habilitación posterior">Suspender / reactivar</button></div></td></tr><tr v-if="!rows.length"><td colspan="8" class="finance-empty">{{ store.loading?'Cargando…':tab==='paid'?'La cola de reactivaciones se habilitará después de la conciliación y el piloto.':'Sin contratos en esta bandeja.' }}</td></tr></tbody></table></div><p class="finance-footnote">No se ejecutan escaneos de deuda ni comandos OLT / MikroTik / IPTV. La reconexión no forma parte de registrar un pago.</p></section>
 <Teleport to="body"><div v-if="detailContract&&(detail||checking||events)" class="modal-overlay"><section class="modal-panel finance-dialog"><div class="finance-dialog-head"><h2>{{ detailContract.contract_number }} · revisión</h2><button aria-label="Cerrar revisión" @click="detailContract=null;detail=null;events=null">×</button></div><p v-if="checking">Verificando relaciones en la base, sin contactar equipos…</p><template v-if="detail"><p>Contrato exacto: {{ detail.contractId }}</p><p>ONT vinculada: {{ detail.ontId??'Sin identificación inequívoca' }}</p><p v-for="reason in detail.reasons" :key="reason" class="finance-error">{{ reason }}</p><p class="finance-help">La ejecución está bloqueada aunque los vínculos sean correctos. Falta autorizar la fase técnica y validar el estado real.</p></template><template v-if="events"><p v-for="(e,n) in events" :key="n" class="finance-history-line">{{ new Date(e.created_at).toLocaleString('es-PE',{timeZone:'America/Lima'}) }} · {{ e.event_type }}<small>{{ e.detail }} · Responsable {{ e.created_by??'No registrado en histórico' }}</small></p><p v-if="!events.length">Sin eventos registrados.</p></template></section></div></Teleport>
 </AppLayout>
</template>
<style src="../../components/facturacion/finance.css"></style>
